-- Full content + 12-point SEO pass for the three "Luxury Solo Egypt" tours,
-- same pattern as update-family-tours-full.sql +
-- update-family-tours-seo-full.sql, combined into one script this time.
--
-- Requires tours.faqs and tours.schema_markup to exist first (see
-- update-family-tours-seo-full.sql's header for the migration step).
--
-- Old -> new slugs (301 redirects added to server/tour-redirects.ts):
--   7-day-solo-travel-egypt -> 7-day-egypt-tour
--   9-day-solo-egypt -> 10-day-egypt-tour
--   solo-vacation-packages-luxury-egypt-5-day-tour -> 12-days-egypt-tour
--
-- No em dash or en dash anywhere in any text field, per this pass's
-- explicit instruction (broader than the earlier "prose only" convention
-- used for destinations) — itinerary day titles use a colon instead of the
-- em-dash-separator style update-family-tours-full.sql used
-- ("Giza: Dahshur and Memphis, Before the Crowds", not "Giza — ...").
-- seo_title keeps its en dash before the site name, matching this
-- project's standing seo_title/meta_description exemption and the literal
-- text given for these three.
--
-- description is real HTML (one <h3> keyword-variation subheading + 1-2
-- internal links to real destination pages per tour) for the same reason
-- as the family tours: legacyTextToHtml.ts only auto-wraps plain text once
-- it detects zero HTML tags, so any tag means the whole field must already
-- be well-formed HTML. No hotel links this time — the itinerary uses
-- generic accommodation labels ("Boutique hotel, Giza") rather than named
-- properties, so there's no real hotel record to link to.
--
-- FAQ entries include a generated id (see backfill-faq-ids.sql /
-- update-family-tours-seo-full.sql's header for why this matters).
--
-- gallery_alt is mapped positionally against whatever gallery array
-- actually exists per tour, same unnest ... WITH ORDINALITY approach as
-- the other gallery_alt scripts in this directory.

-- 7-day-solo-travel-egypt -> 7-day-egypt-tour
UPDATE tours
SET
  slug = '7-day-egypt-tour',
  title = '7 Day Egypt Tour: Solo Journey Beyond the Crowds',
  duration = '7 Days / 6 Nights',
  description = '<p>Egypt rewards travelers who arrive alone with something it rarely offers groups: silence. This 7 day Egypt tour is built around the quieter corners of the country, beginning not at the Giza plateau with everyone else but at Dahshur, where you may have a pyramid''s interior entirely to yourself.</p>
<h3>Why This 7 Day Egypt Tour Works So Well Alone</h3>
<p>The itinerary favors depth over coverage. In <a href="/egypt-travel-guide/attractions-in-luxor">Luxor</a>, you explore Deir el-Medina, where the artisans who carved the royal tombs actually lived, and Dendera, whose ceiling paintings retain colour found almost nowhere else. These are the sites Egyptologists themselves return to, and they are almost always empty.</p>
<p>Evenings belong to you. A Cairo café where the city''s writers gather, a craft workshop where you make something with your hands, a felucca sail in <a href="/egypt-travel-guide/aswan-egypt-attractions">Aswan</a> with just the boatman as the sun drops behind the west bank. Traveling solo means the schedule bends to your interests rather than a group consensus.</p>',
  itinerary = '[{"day":1,"title":"Giza: Dahshur and Memphis, Before the Crowds","description":"Rather than beginning at the Giza plateau with everyone else, your first day heads south to Dahshur, where the Bent and Red Pyramids stand almost entirely empty of visitors. You will likely have the Red Pyramid''s interior to yourself, a genuinely rare experience at any Egyptian monument. The afternoon continues to Memphis, Egypt''s ancient first capital, where a colossal fallen statue of Ramesses II rests in near solitude. It is a deliberately quiet introduction to a country most people first encounter through crowds.","activities":[],"lat":29.9792,"lng":31.1342,"placeName":"Giza, Egypt","meals":["Dinner"],"accommodation":"Boutique hotel, Giza"},{"day":2,"title":"Giza: Sunrise at the Plateau and an Evening in Zamalek","description":"You reach the Giza pyramids at sunrise, well before the tour buses arrive, when the light is at its best and the plateau is close to silent. Your Egyptologist keeps the pace unhurried, leaving room to sit, photograph, and simply absorb the scale. The evening shifts entirely: a walk through Zamalek''s tree-lined streets, an independent bookshop, and a café where Cairo''s writers and artists actually spend their evenings, rather than a hotel restaurant.","activities":[],"lat":29.9792,"lng":31.1342,"placeName":"Giza, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Giza"},{"day":3,"title":"Cairo: Islamic Cairo on Foot and a Craft Workshop","description":"A full day exploring Islamic Cairo the way it deserves, on foot and slowly. Ibn Tulun Mosque, Cairo''s oldest intact mosque, offers a remarkably peaceful space for reflection, and the climb up its spiral minaret rewards you with a view few visitors ever see. In the afternoon, a hands-on session with a Cairo craftsman, working in copper or traditional woodwork, replaces the usual bazaar shopping stop with something you actually make yourself.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Cairo"},{"day":4,"title":"Fly to Luxor: Deir el-Medina and the Tombs of the Nobles","description":"In Luxor, you skip the Valley of the Kings entirely on this first day. Instead, Deir el-Medina reveals where the artisans who built the royal tombs actually lived, and the Tombs of the Nobles hold paintings of ordinary life, harvests, banquets, and music, rather than gods and afterlife formulas. These are the sites Egyptologists themselves find most interesting, and they are almost always quiet.","activities":[],"lat":25.6872,"lng":32.6396,"placeName":"Luxor, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Luxor"},{"day":5,"title":"Luxor: Dendera Day Trip","description":"A drive north brings you to Dendera, one of Egypt''s most complete and least visited temple complexes, where the ceiling paintings retain their original color in a way almost nowhere else in Egypt does. Standing in the hypostyle hall with no one else present is a genuinely different experience from Karnak at midday. The return to Luxor leaves the evening open, with no fixed schedule.","activities":[],"lat":25.6872,"lng":32.6396,"placeName":"Luxor, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Luxor"},{"day":6,"title":"Fly to Aswan: Nubian Culture and an Evening Alone on the Nile","description":"Aswan''s Nubian community offers something no monument can: a living culture with its own language, music, and architecture. You spend time in a Nubian home, sharing a meal and conversation rather than photographing from a distance. Later, a solo felucca sail at sunset, with just the boatman, closes the day in the kind of quiet that group travel rarely allows.","activities":[],"lat":24.0889,"lng":32.8998,"placeName":"Aswan, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Aswan"},{"day":7,"title":"Fly to Cairo: Departure","description":"A morning flight returns you to Cairo. Depending on your departure time, there may be space for a final stop, perhaps the Coptic Museum''s quieter halls or simply a last coffee in a Cairo café. A private transfer takes you to the airport, ending a week built around depth rather than coverage.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast"]}]'::jsonb,
  includes = ARRAY['6 nights boutique accommodation', 'All meals daily (breakfast, lunch, and dinner)', 'Private licensed Egyptologist guide throughout', 'Internal domestic flights (Cairo to Luxor, Luxor to Aswan, Aswan to Cairo)', 'All private transfers in air-conditioned vehicles', 'Private entry and guided access to all listed archaeological sites', 'Traditional craft workshop session in Cairo', 'Nubian home visit and meal in Aswan', 'Private felucca sail on the Nile', 'Gratuities for guides and drivers', '24/7 concierge contact throughout your journey']::text[],
  excludes = ARRAY['International flights', 'Egypt entry visa', 'Travel insurance', 'Personal expenses', 'Optional activities not mentioned in the itinerary', 'Any items not specifically listed above']::text[],
  hero_image_alt = 'Solo traveler at Dahshur pyramids on a private 7 day Egypt tour',
  gallery_alt = (
    SELECT COALESCE(jsonb_object_agg(g.url, a.alt_text), '{}'::jsonb)
    FROM unnest(gallery) WITH ORDINALITY AS g(url, ord)
    JOIN unnest(ARRAY['7 day Egypt tour: solo traveler inside the Red Pyramid at Dahshur', '7 day Egypt tour: sunrise at the Giza pyramid plateau', '7 day Egypt tour: Ibn Tulun Mosque in Islamic Cairo', '7 day Egypt tour: Deir el-Medina artisan tombs in Luxor', '7 day Egypt tour: the painted hypostyle hall at Dendera Temple', '7 day Egypt tour: a Nubian home visit near Aswan', '7 day Egypt tour: a solo felucca sail on the Nile at sunset', '7 day Egypt tour: traditional craft workshop in Cairo']) WITH ORDINALITY AS a(alt_text, ord) ON g.ord = a.ord
  ),
  focus_keyword = '7 day egypt tour',
  seo_title = '7 Day Egypt Tour | Private Solo Journey – iLuxury Egypt',
  meta_description = 'A private 7 day Egypt tour built for solo travelers, visiting quiet pyramid fields, artisan tombs, and Nubian homes away from the crowds.',
  schema_type = 'TouristTrip',
  faqs = '[{"id":"bc4fc0ac-cafe-4731-aa30-4ca5a8a4b6da","question":"Is a 7 day Egypt tour long enough to see the highlights?","answer":"Seven days covers Giza, Cairo, Luxor, and Aswan comfortably when the itinerary is well designed. This tour deliberately trades some famous sites for quieter alternatives, which often makes a shorter trip feel richer than a longer, more rushed one."},{"id":"1b0ee31e-5a46-4d9d-9461-de8d1480e7be","question":"Is Egypt safe for solo travelers?","answer":"Egypt is generally safe for solo travel, particularly with a private guide and driver handling logistics. Having someone who knows each city removes the friction that solo travelers most often encounter, from navigation to negotiating at sites."},{"id":"080ef0f4-091e-4acc-8f8a-02b1dc83b93d","question":"Is this tour suitable for solo female travelers?","answer":"Yes. A private guide and pre-arranged transport significantly reduce the challenges solo female travelers sometimes face in Egypt, and accommodation is selected with comfort and security in mind throughout."},{"id":"a4889381-10c0-4882-a949-58528e5d7d48","question":"What is the single supplement for a solo traveler?","answer":"Pricing for solo travelers reflects private accommodation without sharing. Exact figures depend on travel dates and hotel selection, and our team provides a clear breakdown before booking."},{"id":"e8b8920c-bea0-4295-8a75-cf396970ba6b","question":"Are domestic flights included in this 7 day Egypt tour?","answer":"Yes, flights between Cairo, Luxor, and Aswan are included, along with all private transfers. This avoids long overnight drives and preserves more time at the sites themselves."},{"id":"c9741c51-a885-4c4e-ab27-35638c3a3c7d","question":"Can the itinerary be adjusted once I arrive?","answer":"Yes, and this is one of solo travel''s real advantages. Because there is no group consensus to accommodate, your guide can extend time at a site that captures your interest or move on earlier if you prefer."},{"id":"fe03a5d5-8be5-4deb-898f-557285d12db5","question":"What is the best time of year for this itinerary?","answer":"October through April offers the most comfortable temperatures for walking sites in Upper Egypt. Summer travel is possible but requires earlier starts and longer midday breaks."}]'::jsonb
WHERE slug = '7-day-solo-travel-egypt';

-- 9-day-solo-egypt -> 10-day-egypt-tour
UPDATE tours
SET
  slug = '10-day-egypt-tour',
  title = '10 Day Egypt Tour: Siwa Oasis, Abydos & the Nile',
  duration = '10 Days / 9 Nights',
  description = '<p>This 10 day Egypt tour takes a route almost no itinerary attempts, pairing the country''s ancient monuments with three full days deep in the Western Desert at Siwa Oasis. Siwa is a Berber-speaking community with its own language, salt-and-mud architecture, and a pace of life unchanged for generations.</p>
<h3>What Makes This 10 Day Egypt Tour Different</h3>
<p>The archaeological sites are chosen for the same reason. Abu Rawash and Abu Sir are largely empty pyramid fields where construction methods can be read directly from the stone. Abydos holds the Temple of Seti I, whose relief carving is considered the finest to survive from any period, and almost no travelers make the journey there.</p>
<p>A night in the open desert, with dinner served under a sky free of light pollution for hundreds of kilometers, sits at the itinerary''s center. Karnak in <a href="/egypt-travel-guide/attractions-in-luxor">Luxor</a> is visited after dark rather than at midday, when the lit columns make it a fundamentally different building.</p>',
  itinerary = '[{"day":1,"title":"Giza: Abu Rawash and the Forgotten Pyramid","description":"Your journey opens at Abu Rawash, the ruined pyramid of Djedefre that almost no visitor ever sees, sitting on a desert ridge north of Giza. What remains is mostly foundation and rubble, which is precisely what makes it interesting: you can read the construction methods directly from the stone. The afternoon continues to Abu Sir, another largely empty pyramid field, before settling into Giza for the evening.","activities":[],"lat":29.9792,"lng":31.1342,"placeName":"Giza, Egypt","meals":["Dinner"],"accommodation":"Boutique hotel, Giza"},{"day":2,"title":"Giza: Sunrise Plateau and the Solar Boat","description":"You arrive at the Giza plateau at first light, when the site belongs to almost no one. Beyond the three main pyramids, your Egyptologist takes you to the queens'' pyramids and the workers'' cemetery, areas most itineraries skip entirely. The Solar Boat Museum follows, where Khufu''s reassembled funerary vessel offers a startlingly intimate encounter with ancient craftsmanship after a morning of monumental scale.","activities":[],"lat":29.9792,"lng":31.1342,"placeName":"Giza, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Giza"},{"day":3,"title":"Cairo: Coptic Cairo and the Egyptian Museum''s Quiet Rooms","description":"Old Cairo''s churches and the Ben Ezra Synagogue reveal a layered religious history rarely given proper time. In the afternoon at the Egyptian Museum, your guide focuses on the less-visited upper galleries rather than the crowded Tutankhamun rooms, where you can examine painted coffins and everyday objects in relative solitude.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Cairo"},{"day":4,"title":"Drive to Siwa Oasis: Into the Western Desert","description":"A long drive west takes you deep into the Western Desert toward Siwa, and the drive itself is part of the experience as the landscape empties completely. Arriving in Siwa feels like entering a different country: a Berber-speaking community with its own language, architecture built from salt and mud, and a pace of life unchanged for generations.","activities":[],"lat":29.2032,"lng":25.5196,"placeName":"Siwa Oasis, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Eco-lodge, Siwa Oasis"},{"day":5,"title":"Siwa: Temple of the Oracle and Shali at Dusk","description":"Alexander the Great crossed this same desert to consult Siwa''s Oracle, and standing in the temple''s ruins today, that journey feels comprehensible. The afternoon is unstructured: float in a salt lake, walk through olive groves, or simply rest. At dusk, the Shali Fortress ruins catch the last light, and the silence is absolute.","activities":[],"lat":29.2032,"lng":25.5196,"placeName":"Siwa Oasis, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Eco-lodge, Siwa Oasis"},{"day":6,"title":"Siwa: Great Sand Sea and a Night Under the Stars","description":"A 4x4 crosses into the Great Sand Sea, where dunes stretch unbroken toward Libya. You stop at Bir Wahed, a hot spring bubbling beside a cold one at the desert''s edge. As night falls, dinner is served in the open desert, and with no light pollution for hundreds of kilometers, the sky is as clear as it gets anywhere on Earth.","activities":[],"lat":29.2032,"lng":25.5196,"placeName":"Siwa Oasis, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Eco-lodge, Siwa Oasis"},{"day":7,"title":"Return to Cairo, Fly to Luxor: Karnak After Hours","description":"The drive back to Cairo connects to an evening flight south to Luxor. Rather than a first visit to Karnak in the midday crush, you arrive at the temple in the evening, when the columns are lit and the complex holds a fraction of its daytime crowd. It is a completely different building at night.","activities":[],"lat":25.6872,"lng":32.6396,"placeName":"Luxor, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Luxor"},{"day":8,"title":"Luxor: Abydos and the Osireion","description":"A drive north brings you to Abydos, ancient Egypt''s most sacred pilgrimage site and the location of the Temple of Seti I, whose relief carving is widely considered the finest surviving from any period. The adjacent Osireion, a mysterious subterranean structure, remains debated by Egyptologists. Very few travelers make this journey, which is exactly why it rewards it.","activities":[],"lat":25.6872,"lng":32.6396,"placeName":"Luxor, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Luxor"},{"day":9,"title":"Fly to Aswan: Elephantine Island, Return to Cairo","description":"Aswan begins on Elephantine Island, one of Egypt''s oldest continuously inhabited places, where the ancient Nilometer once measured the annual flood. After a morning exploring the island''s ruins and the Nubian Museum''s remarkable collection, an evening flight returns you to Cairo, leaving you comfortably positioned for departure without any rush.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Cairo"},{"day":10,"title":"Cairo: Departure","description":"Your final morning in Cairo is unstructured, whether that means a last visit to a favorite site, a quiet coffee in Zamalek, or simply resting before your flight. A private transfer takes you to the airport at your convenience, closing ten days that ranged from empty pyramid fields to the deep Western Desert.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast"]}]'::jsonb,
  includes = ARRAY['9 nights accommodation in boutique hotels and a desert eco-lodge', 'All meals daily (breakfast, lunch, and dinner)', 'Private licensed Egyptologist guide throughout', 'Internal domestic flights (Cairo to Luxor, Luxor to Aswan, Aswan to Cairo)', 'All private transfers in air-conditioned vehicles, including the Siwa road journey', '4x4 desert excursion into the Great Sand Sea', 'Open-air desert dinner in Siwa', 'Evening access to Karnak Temple', 'Private entry and guided access to all listed archaeological sites', 'Gratuities for guides and drivers', '24/7 concierge contact throughout your journey']::text[],
  excludes = ARRAY['International flights', 'Egypt entry visa', 'Travel insurance', 'Personal expenses', 'Optional activities not mentioned in the itinerary', 'Any items not specifically listed above']::text[],
  hero_image_alt = 'Great Sand Sea dunes at Siwa Oasis on a private 10 day Egypt tour',
  gallery_alt = (
    SELECT COALESCE(jsonb_object_agg(g.url, a.alt_text), '{}'::jsonb)
    FROM unnest(gallery) WITH ORDINALITY AS g(url, ord)
    JOIN unnest(ARRAY['10 day Egypt tour: the ruined pyramid of Djedefre at Abu Rawash', '10 day Egypt tour: sunrise at the Giza pyramid plateau', '10 day Egypt tour: Coptic Cairo''s ancient churches', '10 day Egypt tour: salt and mud architecture in Siwa Oasis', '10 day Egypt tour: the Temple of the Oracle in Siwa', '10 day Egypt tour: dunes of the Great Sand Sea at dusk', '10 day Egypt tour: Karnak Temple illuminated at night', '10 day Egypt tour: the Temple of Seti I at Abydos', '10 day Egypt tour: the ancient Nilometer on Elephantine Island']) WITH ORDINALITY AS a(alt_text, ord) ON g.ord = a.ord
  ),
  focus_keyword = '10 day egypt tour',
  seo_title = '10 Day Egypt Tour | Siwa & Nile Private Journey',
  meta_description = 'A private 10 day Egypt tour combining the Western Desert at Siwa Oasis with Abydos, Karnak after hours, and Nubian Aswan, built for solo travelers.',
  schema_type = 'TouristTrip',
  faqs = '[{"id":"8f4a2953-499c-4640-a900-ca20cbe56fce","question":"Is Siwa Oasis worth including in a 10 day Egypt tour?","answer":"For travelers who want more than the standard Nile Valley route, Siwa is the itinerary''s most memorable segment. It requires a long desert drive, but the Berber culture, salt lakes, and Great Sand Sea offer an experience unavailable anywhere else in Egypt."},{"id":"cc3cef77-218d-4b63-bc39-248e018266bd","question":"How long is the drive from Cairo to Siwa?","answer":"The drive takes roughly eight hours through the Western Desert. It is broken with stops, and the changing landscape becomes part of the experience rather than simply transit time between destinations."},{"id":"d8c9ba9e-9eb1-41d0-a123-d8f99ae64b20","question":"What is Abydos and why visit it?","answer":"Abydos was ancient Egypt''s most sacred pilgrimage site, and the Temple of Seti I there preserves relief carving of exceptional quality. The adjacent Osireion, a subterranean structure still debated by Egyptologists, adds genuine mystery to the visit."},{"id":"63da2f85-56f1-4d62-8b59-02c8de4c4aa4","question":"Is the desert night comfortable?","answer":"Desert nights are cool even in warmer months, and appropriate bedding and layers are provided. For most travelers, the clarity of the night sky more than compensates for the basic conditions."},{"id":"8c091c93-0f8d-48a8-9852-322a15f666c3","question":"Does this 10 day Egypt tour include domestic flights?","answer":"Yes, flights between Cairo, Luxor, and Aswan are included, alongside the Siwa road journey and all private transfers throughout."},{"id":"001ef90d-62f4-4239-98dc-27fc31fc9705","question":"Is this itinerary physically demanding?","answer":"Moderately. The Siwa segment involves long drives and some walking on uneven desert terrain, while temple visits require standing and walking in heat. It suits travelers in reasonable health rather than those needing minimal exertion."},{"id":"d22c1252-4e34-487c-83c6-f0a35905cdbc","question":"Can Siwa be replaced with something else?","answer":"Yes, though it is the itinerary''s defining feature. Travelers preferring coastal relaxation may be better suited to our 12 day itinerary, which includes the Red Sea instead."}]'::jsonb
WHERE slug = '9-day-solo-egypt';

-- solo-vacation-packages-luxury-egypt-5-day-tour -> 12-days-egypt-tour
UPDATE tours
SET
  slug = '12-days-egypt-tour',
  title = '12 Days Egypt Tour: Alexandria, Nile & Red Sea',
  duration = '12 Days / 11 Nights',
  description = '<p>This 12 days Egypt tour covers a fuller span of the country''s history than most itineraries attempt, moving from pharaonic Saqqara through Greek and Roman Alexandria to the Red Sea coast. Alexandria in particular feels unlike anywhere else in Egypt, a Mediterranean city with Roman amphitheatres and a literary history of its own.</p>
<h3>How This 12 Days Egypt Tour Balances History and Rest</h3>
<p>Archaeological highlights are deliberately varied. The Serapeum at Saqqara, a vast underground gallery of granite sarcophagi built for sacred bulls, ranks among Egypt''s strangest spaces. Abu Simbel''s colossal cliff temples near <a href="/egypt-travel-guide/aswan-egypt-attractions">Aswan</a>, visited before the tour groups arrive, deliver a completely different encounter at that hour. In <a href="/egypt-travel-guide/alexandria-egypt-attractions">Alexandria</a>, Roman catacombs sit a short drive from a Mediterranean corniche most visitors never expect from Egypt.</p>
<p>The final days shift entirely. Two nights on the Red Sea offer open water, world-class diving for those certified, and something increasingly rare in structured travel: a day with no schedule at all, after more than a week of intensive exploration.</p>',
  itinerary = '[{"day":1,"title":"Giza: Saqqara''s Lesser Tombs and the Serapeum","description":"Your journey begins at Saqqara, but rather than only the Step Pyramid, you spend time in the mastaba tombs of Ti and Mereruka, where relief carvings of daily life remain remarkably crisp. The Serapeum, a vast underground gallery of granite sarcophagi built for sacred bulls, offers one of Egypt''s strangest and most atmospheric spaces, and it is usually nearly empty.","activities":[],"lat":29.9792,"lng":31.1342,"placeName":"Giza, Egypt","meals":["Dinner"],"accommodation":"Boutique hotel, Giza"},{"day":2,"title":"Giza: The Plateau at Dawn and the Grand Egyptian Museum","description":"An early start brings you to the Giza pyramids before the crowds, with time to walk the site properly rather than following a fixed loop. The afternoon moves to the Grand Egyptian Museum, where your Egyptologist focuses on specific collections aligned with your interests instead of attempting the entire building in one visit.","activities":[],"lat":29.9792,"lng":31.1342,"placeName":"Giza, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Giza"},{"day":3,"title":"Drive to Alexandria: The Catacombs and a Mediterranean Evening","description":"A drive north brings you to Alexandria, a city that feels entirely unlike the rest of Egypt. The Catacombs of Kom el Shoqafa descend three levels into bedrock, blending Egyptian, Greek, and Roman funerary traditions in a single structure. The evening belongs to the corniche, where Alexandria''s Mediterranean character is most apparent.","activities":[],"lat":31.2001,"lng":29.9187,"placeName":"Alexandria, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Alexandria"},{"day":4,"title":"Alexandria: Kom el Dikka and the Cavafy Museum","description":"Kom el Dikka preserves Egypt''s only well-known Roman amphitheatre alongside villas and mosaics, a reminder of how thoroughly Roman this city once was. In the afternoon, the Cavafy Museum, the preserved apartment of the Greek poet who lived here for twenty-five years, offers a literary counterpoint to archaeology. The return drive to Cairo follows.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Cairo"},{"day":5,"title":"Fly to Luxor: Medinet Habu and the Ramesseum","description":"In Luxor, you begin on the west bank with Medinet Habu, whose painted reliefs of the Sea Peoples'' invasion retain colour that has survived three thousand years. The Ramesseum follows, where the fallen colossus of Ramesses II inspired Shelley''s poem about the impermanence of power, a fitting reflection for a solo traveller.","activities":[],"lat":25.6872,"lng":32.6396,"placeName":"Luxor, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Luxor"},{"day":6,"title":"Luxor: Valley of the Queens and Howard Carter''s House","description":"The Valley of the Queens holds the tomb of Nefertari, widely regarded as the most beautifully painted burial chamber to survive from the ancient world. Nearby, Howard Carter''s restored house preserves the archaeologist''s equipment and photographs from the 1922 discovery, connecting the tombs you have just visited to the modern history of their rediscovery.","activities":[],"lat":25.6872,"lng":32.6396,"placeName":"Luxor, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Luxor"},{"day":7,"title":"Fly to Aswan: Philae Temple and the Unfinished Obelisk","description":"Philae, relocated stone by stone to save it from rising waters, remains one of Egypt''s most atmospheric temples, approached only by boat. The Unfinished Obelisk in Aswan''s granite quarries lies exactly where ancient workers abandoned it, offering rare insight into how these monuments were actually carved and moved.","activities":[],"lat":24.0889,"lng":32.8998,"placeName":"Aswan, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Aswan"},{"day":8,"title":"Aswan: Abu Simbel Day Trip","description":"An early departure south brings you to Abu Simbel, where Ramesses II''s colossal temples were cut from a cliff face and later relocated in one of the twentieth century''s greatest engineering rescues. Arriving before the main tour groups means the four twenty-metre statues can be experienced in relative quiet, which fundamentally changes the encounter.","activities":[],"lat":24.0889,"lng":32.8998,"placeName":"Aswan, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Aswan"},{"day":9,"title":"Fly to Hurghada: Red Sea Arrival","description":"A short flight carries you from ancient monuments to the Red Sea coast. The afternoon is entirely unstructured, whether that means swimming, reading by the water, or simply doing nothing at all after eight days of intensive exploration. This is the journey''s deliberate change of pace.","activities":[],"lat":27.2579,"lng":33.8116,"placeName":"Hurghada, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Beachfront hotel, Hurghada"},{"day":10,"title":"Hurghada: Diving or Doing Nothing","description":"A full day with no fixed schedule. For divers, the Red Sea offers some of the world''s clearest water and healthiest reefs, with a dive on the SS Thistlegorm wreck available for certified divers. For everyone else, the day is simply open, an increasingly rare luxury in structured travel.","activities":[],"lat":27.2579,"lng":33.8116,"placeName":"Hurghada, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Beachfront hotel, Hurghada"},{"day":11,"title":"Fly to Cairo: Islamic Cairo on Foot","description":"An early flight returns you to Cairo with the full day ahead. Al-Muizz Street holds the highest concentration of medieval Islamic architecture anywhere in the world, and walking it slowly, stopping at Sultan Hassan Mosque and Bab Zuweila, provides a fitting final chapter after two weeks spanning pharaonic, Greek, Roman, and Islamic Egypt.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast","Lunch","Dinner"],"accommodation":"Boutique hotel, Cairo"},{"day":12,"title":"Cairo: Departure","description":"Your final morning is yours, unhurried and unscheduled. A private transfer takes you to the airport whenever suits your flight, closing twelve days that covered nearly the full span of Egyptian history and geography.","activities":[],"lat":30.0444,"lng":31.2357,"placeName":"Cairo, Egypt","meals":["Breakfast"]}]'::jsonb,
  includes = ARRAY['11 nights accommodation in boutique and beachfront hotels', 'All meals daily (breakfast, lunch, and dinner)', 'Private licensed Egyptologist guide throughout', 'Internal domestic flights (Cairo to Luxor, Luxor to Aswan, Aswan to Hurghada, Hurghada to Cairo)', 'All private transfers in air-conditioned vehicles, including the Alexandria road journey', 'Abu Simbel day trip with early departure', 'Private entry and guided access to all listed archaeological sites', 'Gratuities for guides and drivers', '24/7 concierge contact throughout your journey']::text[],
  excludes = ARRAY['International flights', 'Egypt entry visa', 'Travel insurance', 'Personal expenses', 'Optional activities not mentioned in the itinerary', 'Any items not specifically listed above']::text[],
  hero_image_alt = 'Abu Simbel temples at dawn on a private 12 days Egypt tour',
  gallery_alt = (
    SELECT COALESCE(jsonb_object_agg(g.url, a.alt_text), '{}'::jsonb)
    FROM unnest(gallery) WITH ORDINALITY AS g(url, ord)
    JOIN unnest(ARRAY['12 days Egypt tour: the Serapeum''s granite sarcophagi at Saqqara', '12 days Egypt tour: sunrise at the Giza pyramid plateau', '12 days Egypt tour: the Catacombs of Kom el Shoqafa in Alexandria', '12 days Egypt tour: the Roman amphitheatre at Kom el Dikka', '12 days Egypt tour: painted reliefs at Medinet Habu in Luxor', '12 days Egypt tour: the tomb of Nefertari in the Valley of the Queens', '12 days Egypt tour: Philae Temple approached by boat in Aswan', '12 days Egypt tour: the colossal statues of Abu Simbel at dawn', '12 days Egypt tour: Red Sea coastline in Hurghada', '12 days Egypt tour: medieval architecture along Al-Muizz Street']) WITH ORDINALITY AS a(alt_text, ord) ON g.ord = a.ord
  ),
  focus_keyword = '12 days egypt tour',
  seo_title = '12 Days Egypt Tour | Alexandria to Red Sea Private',
  meta_description = 'A private 12 days Egypt tour spanning Saqqara''s Serapeum, Mediterranean Alexandria, Abu Simbel, and Red Sea diving, designed for solo travelers.',
  schema_type = 'TouristTrip',
  faqs = '[{"id":"6a16d4e7-73b7-4b2a-b978-45859b97166f","question":"What makes a 12 days Egypt tour worth the extra time?","answer":"Twelve days allows Alexandria and the Red Sea alongside the Nile Valley, meaning you experience Mediterranean, pharaonic, and coastal Egypt rather than one region stretched thin across more days."},{"id":"28fcb664-1c62-4b67-ae38-975b59f60a65","question":"Is Alexandria worth visiting on an Egypt itinerary?","answer":"For travelers interested in Greek and Roman history, yes. Alexandria''s catacombs, Roman amphitheatre, and literary heritage offer a genuinely different Egypt from the pharaonic sites further south."},{"id":"0a693fc3-34f7-4429-a62b-003201ab9b0f","question":"Can I dive the SS Thistlegorm on this tour?","answer":"Certified divers can arrange a dive on the Thistlegorm wreck during the Hurghada segment. Non-divers have the same days entirely free for swimming or rest."},{"id":"c478fa84-209f-4107-9264-4892fdee72c8","question":"How early is the Abu Simbel departure?","answer":"Departures are early, typically before dawn, which is precisely what allows the site to be experienced before the main tour groups arrive. Most travelers find the trade-off worthwhile."},{"id":"0c210a9e-c80a-4c0c-830f-80b77eed72d3","question":"Are all domestic flights included in this 12 days Egypt tour?","answer":"Yes, flights between Cairo, Luxor, Aswan, and Hurghada are included, along with the Alexandria road journey and all private transfers."},{"id":"af51e639-2019-41a7-ba79-125b429c9b6e","question":"Is there enough downtime in this itinerary?","answer":"The Red Sea segment provides two deliberately unstructured days, and several other days end without evening activities, leaving time to rest between more demanding site visits."},{"id":"b61ecb59-bf18-4a74-a50f-9ba4dbe3856d","question":"Can the Red Sea portion be extended?","answer":"Yes, additional nights in Hurghada can be arranged, and the itinerary can be adjusted to trade a historical day for further coastal time if preferred."}]'::jsonb
WHERE slug = 'solo-vacation-packages-luxury-egypt-5-day-tour';
